def verify_costas(perm):
    n = len(perm)
    vectors = set()
    for c1 in range(n):
        for c2 in range(c1+1, n):
            dc = c2 - c1
            dr = perm[c2] - perm[c1]
            v = (dr, dc)
            if v in vectors:
                return False
            vectors.add(v)
    return True

def lempel_golomb(p, g, h):
    """Lempel-Golomb construction: order p-2"""
    log_h = {}
    val = 1
    for i in range(p-1):
        log_h[val] = i
        val = (val * h) % p

    perm = []
    for i in range(1, p-1):  # i = 1 to p-2
        gi = pow(g, i, p)
        val = (1 - gi) % p
        if val == 0:
            return None
        perm.append(log_h[val])
    return perm

def is_primitive_root(g, p):
    n = p - 1
    val = 1
    for i in range(1, n+1):
        val = (val * g) % p
        if val == 1 and i < n:
            return False
    return True

p = 17
primitive_roots = [g for g in range(2, p) if is_primitive_root(g, p)]
print(f"Primitive roots of {p}: {primitive_roots}")

found = []
for g in primitive_roots:
    for h in primitive_roots:
        perm = lempel_golomb(p, g, h)
        if perm is not None and len(perm) == 15 and len(set(perm)) == 15 and verify_costas(perm):
            print(f"Found Costas array with g={g}, h={h}: {perm}")
            found.append(perm)

if not found:
    print("No valid arrays found with Lempel-Golomb")
